  1	//! Short-Time Fourier Transform and analytic signal computation.
  2	
  3	use num_complex::Complex;
  4	use rustfft::FftPlanner;
  5	
  6	use crate::error::{MusicError, Result};
  7	
  8	/// Computes the analytic signal of a real-valued input using the Hilbert transform.
  9	///
 10	/// The analytic signal `z(t) = x(t) + j·H{x(t)}` has a one-sided spectrum; its magnitude is the
 11	/// instantaneous envelope and its argument is the instantaneous phase.
 12	///
 13	/// # Algorithm
 14	/// 1. Forward FFT of the real input.
 15	/// 2. Apply the one-sided spectral window H: `H[0] = 1`, `H[k] = 2` for the positive
 16	///    frequencies `1 ≤ k < (N+1)/2`, `H[N/2] = 1` for the Nyquist bin of even N, and `H = 0` for
 17	///    the negative frequencies `k > N/2` (as in `scipy.signal.hilbert`).
 18	/// 3. Inverse FFT → analytic signal.
 19	///
 20	/// # Examples
 21	/// ```
 22	/// use musicrs::analytic_signal;
 23	/// use std::f64::consts::PI;
 24	/// let n = 256;
 25	/// let cos: Vec<f64> = (0..n).map(|i| (2.0 * PI * 10.0 * i as f64 / n as f64).cos()).collect();
 26	/// let z = analytic_signal(&cos);
 27	/// // Magnitude should be approximately 1 everywhere (after transients settle)
 28	/// for &c in &z[10..n-10] {
 29	///     assert!((c.norm() - 1.0).abs() < 0.01);
 30	/// }
 31	/// ```
 32	pub fn analytic_signal(data: &[f64]) -> Vec<Complex<f64>> {
 33	    let n = data.len();
 34	    if n == 0 {
 35	        return Vec::new();
 36	    }
 37	    let mut planner = FftPlanner::<f64>::new();
 38	
 39	    // Forward FFT
 40	    let fft_forward = planner.plan_fft_forward(n);
 41	    let mut spectrum: Vec<Complex<f64>> = data.iter().map(|&x| Complex::new(x, 0.0)).collect();
 42	    fft_forward.process(&mut spectrum);
 43	
 44	    // One-sided spectral window. DC is unchanged; so is the Nyquist bin N/2, which only
 45	    // exists for even N. Odd N has no Nyquist bin: bin (N-1)/2 is a positive frequency.
 46	    for sample in &mut spectrum[1..n.div_ceil(2)] {
 47	        *sample *= 2.0;
 48	    }
 49	    for sample in &mut spectrum[n / 2 + 1..] {
 50	        *sample = Complex::new(0.0, 0.0);
 51	    }
 52	
 53	    // Inverse FFT
 54	    let fft_inverse = planner.plan_fft_inverse(n);
 55	    fft_inverse.process(&mut spectrum);
 56	
 57	    // Normalise
 58	    let norm = n as f64;
 59	    spectrum.iter().map(|c| c / norm).collect()
 60	}
 61	
 62	/// Computes the Short-Time Fourier Transform of a real-valued signal.
 63	///
 64	/// Returns a matrix of shape `[freq_bins][num_windows]` where
 65	/// `freq_bins = nfft / 2 + 1` (single-sided spectrum via real FFT).
 66	///
 67	/// # Arguments
 68	/// * `data`       – Real-valued input samples.
 69	/// * `nfft`       – Window (FFT) size.
 70	/// * `no_overlap` – Number of samples shared between consecutive windows.
 71	///
 72	/// Data shorter than `nfft` gives `nfft / 2 + 1` empty bins.
 73	///
 74	/// # Errors
 75	/// [`MusicError::InvalidNfft`] if `nfft` is 0, [`MusicError::InvalidOverlap`] if
 76	/// `no_overlap >= nfft`.
 77	///
 78	/// # Examples
 79	/// ```
 80	/// use musicrs::stft;
 81	/// use std::f64::consts::PI;
 82	/// let n = 512;
 83	/// let freq_bin = 16usize;
 84	/// let sr = 512.0_f64;
 85	/// let sine: Vec<f64> = (0..n)
 86	///     .map(|i| (2.0 * PI * freq_bin as f64 * i as f64 / sr).sin())
 87	///     .collect();
 88	/// let result = stft(&sine, 64, 0)?;
 89	/// assert_eq!(result.len(), 64 / 2 + 1); // bins 0..=32
 90	/// assert_eq!(result[0].len(), 512 / 64); // non-overlapping windows
 91	/// // 16 cycles per 512 samples is 2 cycles per 64-sample window: bin 2 in every window
 92	/// for w in 0..result[0].len() {
 93	///     let peak = (0..result.len())
 94	///         .max_by(|&a, &b| result[a][w].norm().total_cmp(&result[b][w].norm()))
 95	///         .unwrap();
 96	///     assert_eq!(peak, 2);
 97	/// }
 98	/// # Ok::<(), musicrs::MusicError>(())
 99	/// ```
100	pub fn stft(data: &[f64], nfft: usize, no_overlap: usize) -> Result<Vec<Vec<Complex<f64>>>> {
101	    if nfft == 0 {
102	        return Err(MusicError::InvalidNfft);
103	    }
104	    if no_overlap >= nfft {
105	        return Err(MusicError::InvalidOverlap { no_overlap, nfft });
106	    }
107	
108	    let step = nfft - no_overlap;
109	    let freq_bins = nfft / 2 + 1;
110	    let mut planner = FftPlanner::<f64>::new();
111	    // Use real-to-complex FFT plan (standard forward FFT on real-padded input)
112	    let fft = planner.plan_fft_forward(nfft);
113	
114	    let num_windows = if data.len() >= nfft {
115	        (data.len() - nfft) / step + 1
116	    } else {
117	        0
118	    };
119	
120	    // result[freq_bin][window_index]
121	    let mut result: Vec<Vec<Complex<f64>>> =
122	        vec![vec![Complex::new(0.0, 0.0); num_windows]; freq_bins];
123	
124	    for (win_idx, start) in (0..).zip((0..).step_by(step).take(num_windows)) {
125	        let end = start + nfft;
126	        let mut buf: Vec<Complex<f64>> = data[start..end]
127	            .iter()
128	            .map(|&x| Complex::new(x, 0.0))
129	            .collect();
130	        fft.process(&mut buf);
131	        for bin in 0..freq_bins {
132	            result[bin][win_idx] = buf[bin];
133	        }
134	    }
135	
136	    Ok(result)
137	}
