145	    /// Pure cosine → analytic signal magnitude ≈ 1 (away from edges).
146	    #[test]
147	    fn analytic_signal_cosine_magnitude() {
148	        let n = 256usize;
149	        let f0 = 10.0_f64;
150	        let data: Vec<f64> = (0..n)
151	            .map(|i| (2.0 * PI * f0 * i as f64 / n as f64).cos())
152	            .collect();
153	        let z = analytic_signal(&data);
154	        // Skip 10 samples at each edge where Gibbs artefacts may occur
155	        for c in &z[10..n - 10] {
156	            assert_abs_diff_eq!(c.norm(), 1.0, epsilon = 0.02);
157	        }
158	    }
