160	    /// Analytic signal of a cosine has imaginary part ≈ -sine (shifted by -π/2).
161	    #[test]
162	    fn analytic_signal_imag_is_negative_sine() {
163	        let n = 256usize;
164	        let f0 = 8.0_f64;
