167	            .collect();
168	        let z = analytic_signal(&data);
169	        for (i, zi) in z.iter().enumerate().take(n - 10).skip(10) {
170	            // H{cos(ωt)} = +sin(ωt), so z(t) = cos(ωt) + i·sin(ωt)
171	            let expected_imag = (2.0 * PI * f0 * i as f64 / n as f64).sin();
172	            assert_abs_diff_eq!(zi.im, expected_imag, epsilon = 0.02);
