420	    /// Computes the steering vector for a plane wave arriving from `angle` (radians)
421	    /// at `frequency` (Hz).
422	    ///
423	    /// Element *j* is `exp(+i·2π·f·τⱼ)` where `τⱼ = (pⱼ · d̂) / c` is the projection of
424	    /// antenna *j*'s position onto the arrival direction, divided by the speed of sound. This
425	    /// matches the non-conjugated [`analytic_signal`] and STFT bins
426	    /// (pyMUSIC conjugates its analytic signal and uses `exp(−i·2π·f·τⱼ)`; the two agree below
427	    /// Nyquist). Relative to [`sample_rate`](Self::sample_rate):
428	    /// * above Nyquist the exponent is negated, `exp(−i·2π·f·τⱼ)`, because the recorded tone
429	    ///   is aliased and its phase is conjugated;
430	    /// * within 0.5 Hz of Nyquist the vector is real, `cos(2π·f·τⱼ)`, because the analytic
431	    ///   signal there is real too.
432	    ///
433	    /// # Examples
434	    /// ```
435	    /// use musicrs::MusicEstimator;
436	    /// let est = MusicEstimator::default();
437	    /// let sv = est.steering_vector(0.0, 300.0);
438	    /// assert_eq!(sv.len(), 4);
439	    /// // All elements have unit magnitude
440	    /// for c in sv.iter() {
441	    ///     assert!((c.norm() - 1.0).abs() < 1e-12);
442	    /// }
443	    /// ```
444	    pub fn steering_vector(&self, angle: f64, frequency: f64) -> CVec {
445	        let dir = [angle.cos(), angle.sin()];
446	        // For f < Nyquist (sr/2): analytic signal has positive phase → use +exponent.
447	        // For f > Nyquist: signal aliases in the one-sided FFT; dominant eigenvector
448	        // phase is conjugated → use −exponent.
449	        // At exactly Nyquist (f == sr/2): analytic signal is real; noise subspace is
450	        // also real → use cos(phase) as a real steering vector.
451	        let nyquist = self.sample_rate / 2.0;
452	        let phase_sign = if frequency > nyquist {
453	            -1.0_f64
454	        } else {
455	            1.0_f64
456	        };
457	        let at_nyquist = (frequency - nyquist).abs() < 0.5;
458	        CVec::from_iterator(
459	            self.n_antennas(),
460	            self.antenna_positions.iter().map(|p| {
461	                let delay = (p[0] * dir[0] + p[1] * dir[1]) / SPEED_OF_SOUND;
462	                let phase = phase_sign * 2.0 * PI * frequency * delay;
463	                if at_nyquist {
464	                    // Real steering vector: imaginary part is zero
465	                    Cplx::new(phase.cos(), 0.0)
466	                } else {
467	                    Cplx::from_polar(1.0, phase)
468	                }
469	            }),
470	        )
471	    }
